export const src = (slug: string, small = false) =>
  `/photos/${slug}${small ? '-sm' : ''}.webp`;

export const byCat = (...cats: PhotoCat[]) => photos.filter((p) => cats.includes(p.cat));

export const bySlug = (slug: string): Photo => {
  const p = photos.find((x) => x.slug === slug);
  if (!p) throw new Error(`Unknown photo: ${slug}`);
  return p;
};
